            if (issueTitle.toLowerCase().includes("bug") || issueBody.toLowerCase().includes("bug")) {
              classification = "bug";
              labels.push("bug");
            } else if (issueTitle.toLowerCase().includes("recipe") || issueBody.toLowerCase().includes("recipe")) {
